// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PrivatePool} from "../src/PrivatePool.sol";

contract InvMutTest is Test {
    PrivatePool c;
    function setUp() public { c = new PrivatePool(address(this), address(this), address(this)); }
    function testFuzz_property(uint16 _feeRate, uint8 _baseTokenType) public {
        vm.assume(_feeRate <= 5000);
        address _baseToken = _baseTokenType % 2 == 0 ? address(0) : address(this);
        address _nft = address(0x1);
        uint128 _virtualBaseTokenReserves = 1e18;
        uint128 _virtualNftReserves = 1e18;
        uint56 _changeFee = 1;
        bytes32 _merkleRoot = bytes32(0);
        bool _useStolenNftOracle = false;
        bool _payRoyalties = false;
        c.initialize(
            _baseToken,
            _nft,
            _virtualBaseTokenReserves,
            _virtualNftReserves,
            _changeFee,
            _feeRate,
            _merkleRoot,
            _useStolenNftOracle,
            _payRoyalties
        );
        assertTrue(c.feeRate() == _feeRate);
    }
}
